import { build } from "esbuild";
import { JSDOM } from "jsdom";
import { zipSync, strToU8 } from "fflate";
import { mkdir, readFile, readdir, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import path from "node:path";

export const root = fileURLToPath(new URL("../", import.meta.url));
const browserLoaders = { ".woff": "dataurl", ".woff2": "dataurl", ".ttf": "dataurl", ".svg": "dataurl", ".png": "dataurl", ".gif": "dataurl" };

/** Bundles the exact official library for prompt generation and independent parity checks. */
export async function buildUpstreamReference() {
  const result = await build({
    absWorkingDir: root, bundle: true, platform: "browser", format: "iife", globalName: "OpenUiReference",
    target: "es2020", write: false, legalComments: "inline", loader: { ...browserLoaders, ".css": "empty" },
    define: { "process.env.NODE_ENV": '"production"' },
    stdin: {
      resolveDir: root, sourcefile: "upstream-reference.ts",
      contents: 'import { createElement } from "react"; import { createRoot } from "react-dom/client"; import { Renderer } from "@openuidev/react-lang"; import { ThemeProvider } from "@openuidev/react-ui"; import { openuiLibrary } from "@openuidev/react-ui/genui-lib"; import { PROMPT_OPTIONS } from "./src/prompt-options"; export { createElement, createRoot, Renderer, ThemeProvider, openuiLibrary }; export const prompt = openuiLibrary.prompt(PROMPT_OPTIONS); export const components = Object.keys(openuiLibrary.components).sort();',
    },
  });
  if (result.outputFiles.length !== 1) throw new Error("OpenUI reference must produce one script");
  const script = result.outputFiles[0].text;
  const dom = new JSDOM("<!doctype html>", { url: "https://openui.operit.local/", runScripts: "outside-only", pretendToBeVisual: true });
  try {
    dom.window.eval(script);
    const { prompt, components } = dom.window.OpenUiReference;
    if (typeof prompt !== "string" || prompt.length === 0 || !Array.isArray(components)) throw new Error("Invalid upstream library prompt");
    return { script, prompt, components: Array.from(components) };
  } finally {
    dom.window.close();
  }
}

/** Compiles the readable ToolPkg entry and independent Compose screen using the host's Promise contract. */
export async function buildPluginScripts(prompt) {
  const shared = { absWorkingDir: root, bundle: true, format: "cjs", platform: "neutral", target: "es2020", supported: { "async-await": false }, write: false, charset: "utf8" };
  const main = await build({
    ...shared, entryPoints: ["src/main.ts"], external: ["./ui/index.ui.js"],
    plugins: [{
      name: "openui-library-prompt",
      /** Supplies the prompt generated by this exact dependency lockfile. */
      setup(builder) {
        builder.onResolve({ filter: /^openui:prompt$/ },
          /** Resolves only the plugin's explicit generated prompt module. */
          function resolvePrompt() { return { path: "prompt", namespace: "openui" }; },
        );
        builder.onLoad({ filter: /^prompt$/, namespace: "openui" },
          /** Embeds the upstream instructions without a runtime filesystem read. */
          function loadPrompt() { return { contents: "export default " + JSON.stringify(prompt), loader: "js" }; },
        );
      },
    }],
  });
  const screen = await build({ ...shared, entryPoints: ["src/ui/index.ui.ts"] });
  return { "dist/main.js": main.outputFiles[0].contents, "dist/ui/index.ui.js": screen.outputFiles[0].contents };
}

/** Builds the production renderer from unmodified official packages and embeds static font assets. */
export async function buildBrowser() {
  const result = await build({
    absWorkingDir: root, entryPoints: ["web/app.ts"], outfile: path.join(root, "dist/web/openui.js"),
    bundle: true, format: "iife", platform: "browser", target: "es2020", write: false,
    minify: true, legalComments: "linked", loader: browserLoaders,
    define: { "process.env.NODE_ENV": '"production"' },
  });
  const files = {};
  for (const output of result.outputFiles) files[path.relative(root, output.path).split(path.sep).join("/")] = output.contents;
  files["dist/web/index.html"] = new Uint8Array(await readFile(path.join(root, "web/index.html")));
  return files;
}

/** Includes editable plugin sources in the distributable without copying dependencies or build output. */
async function includeSources(directory, entries) {
  for (const item of await readdir(path.join(root, directory), { withFileTypes: true })) {
    const relative = directory + "/" + item.name;
    if (item.isDirectory()) await includeSources(relative, entries);
    else if (item.isFile()) entries[relative] = new Uint8Array(await readFile(path.join(root, relative)));
  }
}

/** Produces the optional ToolPkg and its matching bundled asset only in this worktree. */
export async function pack() {
  const reference = await buildUpstreamReference();
  const scripts = await buildPluginScripts(reference.prompt);
  const browser = await buildBrowser();
  const entries = { ...scripts, ...browser };
  for (const file of ["manifest.json", "package.json", "pnpm-lock.yaml", "tsconfig.json", "README.md", "THIRD_PARTY_NOTICES.md"]) {
    entries[file] = new Uint8Array(await readFile(path.join(root, file)));
  }
  for (const directory of ["src", "web", "scripts", "tests"]) await includeSources(directory, entries);
  entries["dist/upstream.json"] = strToU8(JSON.stringify({
    repository: "thesysdev/openui", renderer: "@openuidev/react-lang@1.0.2", components: "@openuidev/react-ui@0.18.1",
    library: "openuiLibrary", componentNames: reference.components,
  }, null, 2) + "\n");
  const manifest = JSON.parse(new TextDecoder().decode(entries["manifest.json"]));
  for (const resource of manifest.resources) {
    if (!(resource.path in entries)) throw new Error("Missing declared OpenUI resource: " + resource.path);
  }
  for (const [relative, content] of Object.entries({ ...scripts, ...browser, "dist/upstream.json": entries["dist/upstream.json"] })) {
    await mkdir(path.dirname(path.join(root, relative)), { recursive: true });
    await writeFile(path.join(root, relative), content);
  }
  const archive = zipSync(entries, { level: 9, mtime: new Date("2026-01-01T00:00:00Z") });
  await writeFile(path.join(root, "dist/openui.toolpkg"), archive);
  const asset = path.resolve(root, "../../../../core/crates/runtime/application/assets/plugins/external/openui.toolpkg");
  await mkdir(path.dirname(asset), { recursive: true });
  await writeFile(asset, archive);
  console.log("Packed OpenUI: " + reference.components.length + " upstream components, " + archive.length + " bytes");
  return { entries, reference, archive };
}

if (process.argv[1] === fileURLToPath(import.meta.url)) await pack();
